"""Single Number — XOR cancels every pair.

Time: O(n)   Space: O(1)
"""
from functools import reduce
from operator import xor
from typing import List


class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        return reduce(xor, nums)
